 const spec=specs[s?.metricId];if(!spec||s.companyId!=='PENTA'||s.comparisonScope!==spec.scope||s.accountingStandard!=='JGAAP'||s.comparisonPolicyMode!=='reported_issuer_ratios_with_reviewed_groups'||s.unit!==spec.unit||s.currency!==(spec.unit==='円'?'JPY':'not_applicable')||s.measureKind!==spec.measureKind||s.periodBasis!==spec.periodBasis||s.cycle!=='年度次'||s.automaticAggregationAllowed!==false||s.points?.length!==spec.years.length||s.comparisonPolicyGroups?.length!==spec.years.length)return false;
 const instant=spec.periodBasis==='fiscal_year_end_instant';return s.points.every((p,i)=>{const y=spec.years[i],pin=spec.pins[y],v=p.provenance,g=s.comparisonPolicyGroups[i],start=instant?`${y+1}-03-31`:`${y}-04-01`,end=`${y+1}-03-31`;return p.fiscalYear===y&&p.periodStart===start&&p.periodEnd===end&&(!instant||p.asOf===end)&&p.numericValue===pin.value&&v?.sourceNumericValue===pin.value&&v.sourceUnit===spec.unit&&v.unitConversionFactor===1&&v.accountingStandard==='JGAAP'&&v.sourceDocumentId===pin.doc&&v.sourceFileSha256===pin.hash&&v.documentVersionSha256===pin.hash&&v.pdfPage===pin.page&&eq(v.sourceLocator?.value_bbox,pin.bbox)&&eq(v.metricNativeEvidence,pin.native)&&eq(v.issuerRatioReview,pin.review)&&v.comparisonVerificationId===`penta-${s.metricId}-2015-2025-20261023`&&g?.id===p.comparisonPolicyGroup&&g.status==='source_reviewed_issuer_ratio_group'&&g.periodStart===p.periodStart&&g.periodEnd===p.periodEnd&&g.sourceFileSha256===pin.hash&&g.sourceLocator?.pdf_page===pin.page&&!!g.sourceQuote;});
